import Foundation
import SwiftUI

struct HQTimelineAuthor: Identifiable, Hashable, Sendable {
    let id: String
    let displayName: String
    let isCurrentUser: Bool
}

struct HQTimelineMessage: Identifiable, Hashable, Sendable {
    let id: String
    let rootEventID: String?
    let author: HQTimelineAuthor
    let body: String
    let sentAt: Date

    var isRootMessage: Bool { rootEventID == nil }
}

struct HQTimelineRow: Identifiable, Equatable, Sendable {
    let message: HQTimelineMessage
    let startsAuthorGroup: Bool
    let showsDatePill: Bool

    var id: String { message.id }
}

enum HQTimelineGrouper {
    static let groupingInterval: TimeInterval = 5 * 60

    static func rows(
        from messages: [HQTimelineMessage],
        calendar: Calendar
    ) -> [HQTimelineRow] {
        []
    }
}

import Foundation
import XCTest
@testable import HQIOS

final class HQConversationTimelineTests: XCTestCase {
    func testTimelineKeepsOnlyRootsChronologicalAndGroupsSameAuthorWithinFiveMinutes() {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(secondsFromGMT: 0)!
        let alice = HQTimelineAuthor(id: "alice", displayName: "Alice", isCurrentUser: false)
        let bob = HQTimelineAuthor(id: "bob", displayName: "Bob", isCurrentUser: true)
        let dayOne = Date(timeIntervalSince1970: 1_780_704_000)
        let messages = [
            message("later", author: alice, at: dayOne.addingTimeInterval(240)),
            message("reply", rootEventID: "first", author: alice, at: dayOne.addingTimeInterval(60)),
            message("next-author", author: bob, at: dayOne.addingTimeInterval(250)),
            message("first", author: alice, at: dayOne),
            message("next-day", author: bob, at: dayOne.addingTimeInterval(86_400)),
        ]

        let rows = HQTimelineGrouper.rows(from: messages, calendar: calendar)

        XCTAssertEqual(rows.map(\.id), ["first", "later", "next-author", "next-day"])
        XCTAssertEqual(rows.map(\.startsAuthorGroup), [true, false, true, true])
        XCTAssertEqual(rows.map(\.showsDatePill), [true, false, false, true])
    }

    private func message(
        _ id: String,
        rootEventID: String? = nil,
        author: HQTimelineAuthor,
        at sentAt: Date
    ) -> HQTimelineMessage {
        HQTimelineMessage(
            id: id,
            rootEventID: rootEventID,
            author: author,
            body: id,
            sentAt: sentAt
        )
    }
}

