import Combine
import Foundation

struct HQMessagingTenantFence: Equatable, Hashable, Sendable {
    let subjectID: String
    let generation: UInt64
}

enum HQMessagingConversationID: Equatable, Hashable, Sendable {
    case channel(String)
    case directMessage(String)

    var railID: String {
        switch self {
        case let .channel(id): "ch:\(id)"
        case let .directMessage(personUID): "dm:\(personUID)"
        }
    }
}

enum HQMessagingConversationKind: Equatable, Hashable, Sendable {
    case channel
    case projectChannel
    case directMessage
    case group
}

struct HQMessagingConversationSummary: Identifiable, Equatable, Hashable, Sendable {
    let id: HQMessagingConversationID
    let kind: HQMessagingConversationKind
    let title: String
    let companyUID: String?
    let projectID: String?
    let lastActivityAt: Date?
    var unreadCount: Int
}

struct HQMessagingDirectoryDelta: Equatable, Sendable {
    let fence: HQMessagingTenantFence
    let isSnapshot: Bool
    let reset: Bool
    let cursor: String?
    let changed: [HQMessagingConversationSummary]
    let removedIDs: Set<HQMessagingConversationID>
}

struct HQMessagingDirectoryState: Equatable, Sendable {
    let fence: HQMessagingTenantFence
    var cursor: String?
    var conversations: [HQMessagingConversationSummary]
}

enum HQMessagingDirectoryReducer {
    static func applying(
        _ delta: HQMessagingDirectoryDelta,
        to state: HQMessagingDirectoryState
    ) -> HQMessagingDirectoryState {
        state
    }
}

@MainActor
final class HQMessagingStore: ObservableObject {
    @Published private(set) var directory: HQMessagingDirectoryState
    @Published private(set) var selectedConversationID: HQMessagingConversationID?

    init(fence: HQMessagingTenantFence) {
        directory = HQMessagingDirectoryState(fence: fence, cursor: nil, conversations: [])
    }

    func activate(_ fence: HQMessagingTenantFence) {
        directory = HQMessagingDirectoryState(fence: fence, cursor: nil, conversations: [])
        selectedConversationID = nil
    }

    func apply(_ delta: HQMessagingDirectoryDelta) {
        directory = HQMessagingDirectoryReducer.applying(delta, to: directory)
    }
}

import Foundation
import XCTest
@testable import HQIOS

@MainActor
final class HQMessagingStoreTests: XCTestCase {
    func testSnapshotAndIncrementalDirectoryDeltasMergeByStableConversationIdentity() {
        let fence = HQMessagingTenantFence(subjectID: "subject-a", generation: 7)
        let initial = HQMessagingDirectoryState(fence: fence, cursor: nil, conversations: [])
        let snapshot = HQMessagingDirectoryDelta(
            fence: fence,
            isSnapshot: true,
            reset: false,
            cursor: "cursor-1",
            changed: [
                summary(.channel("launch"), title: "Launch", at: 100, unread: 2),
                summary(.directMessage("person-a"), title: "Ada", at: 90, unread: 1),
            ],
            removedIDs: []
        )

        let afterSnapshot = HQMessagingDirectoryReducer.applying(snapshot, to: initial)
        XCTAssertEqual(afterSnapshot.conversations.map(\.id), [.channel("launch"), .directMessage("person-a")])
        XCTAssertEqual(afterSnapshot.cursor, "cursor-1")

        let incremental = HQMessagingDirectoryDelta(
            fence: fence,
            isSnapshot: false,
            reset: false,
            cursor: "cursor-2",
            changed: [
                summary(.directMessage("person-a"), title: "Ada Lovelace", at: 110, unread: 3),
                summary(.channel("design"), title: "Design", at: 95, unread: 0),
            ],
            removedIDs: [.channel("launch")]
        )

        let merged = HQMessagingDirectoryReducer.applying(incremental, to: afterSnapshot)
        XCTAssertEqual(merged.conversations.map(\.id), [.directMessage("person-a"), .channel("design")])
        XCTAssertEqual(merged.conversations.first?.title, "Ada Lovelace")
        XCTAssertEqual(merged.conversations.first?.unreadCount, 3)
        XCTAssertEqual(merged.cursor, "cursor-2")
    }

    private func summary(
        _ id: HQMessagingConversationID,
        title: String,
        at timestamp: TimeInterval,
        unread: Int
    ) -> HQMessagingConversationSummary {
        HQMessagingConversationSummary(
            id: id,
            kind: id.railID.hasPrefix("ch:") ? .channel : .directMessage,
            title: title,
            companyUID: nil,
            projectID: nil,
            lastActivityAt: Date(timeIntervalSince1970: timestamp),
            unreadCount: unread
        )
    }
}

