+                    .frame(width: min(390, max(320, effectiveWidth * 0.72)))
+                    .background(.background)
+                    .shadow(color: .black.opacity(0.18), radius: 24, x: -6)
+                    .transition(.move(edge: .trailing))
+                }
+            }
+            .inspector(isPresented: Binding(
+                get: { layout == .padSplitWithInspector && model.inspectorTarget != nil },
+                set: { if !$0 { model.inspectorTarget = nil } }
