+private struct HQMessagingCreateView: View {
+    @Environment(\.dismiss) private var dismiss
+    let onCreate: @MainActor (HQMessagingCreateDraft) async throws -> Void
+    @State private var kind: HQMessagingCreateDraft.Kind = .channel
+    @State private var value = ""
+    @State private var isSubmitting = false
+    @State private var errorMessage: String?
+
+    var body: some View {
+        NavigationStack {
+            Form {
+                Picker("Conversation type", selection: $kind) {
+                    ForEach(HQMessagingCreateDraft.Kind.allCases) { kind in
+                        Text(kind.title).tag(kind)
+                    }
+                }
+                .pickerStyle(.segmented)
+
+                TextField(placeholder, text: $value)
+                    .textInputAutocapitalization(kind == .channel ? .never : .words)
+                    .autocorrectionDisabled(kind == .channel)
+                    .accessibilityIdentifier("messages.create.value")
+
+                if let errorMessage {
+                    Text(errorMessage)
+                        .font(.footnote)
+                        .foregroundStyle(.red)
+                        .accessibilityIdentifier("messages.create.error")
+                }
+            }
+            .navigationTitle("New conversation")
+            .navigationBarTitleDisplayMode(.inline)
+            .toolbar {
+                ToolbarItem(placement: .cancellationAction) {
+                    Button("Cancel") { dismiss() }
+                }
+                ToolbarItem(placement: .confirmationAction) {
+                    Button("Create") {
+                        Task { await submit() }
+                    }
+                    .disabled(value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty || isSubmitting)
+                }
+            }
+        }
+        .presentationDetents([.medium])
+        .accessibilityIdentifier("messages.create.sheet")
+    }
+
+    private var placeholder: String {
+        switch kind {
+        case .channel: "Channel name"
+        case .directMessage: "Name or email"
+        case .group: "People"
+        }
+    }
+
+    private func submit() async {
+        isSubmitting = true
+        errorMessage = nil
+        do {
+            try await onCreate(.init(kind: kind, nameOrRecipient: value.trimmingCharacters(in: .whitespacesAndNewlines)))
+            dismiss()
+        } catch {
+            errorMessage = error.localizedDescription
+            isSubmitting = false
+        }
+    }
+}

