import Combine
import Foundation
import SwiftUI

struct HQMessagingTenantContext: Equatable, Sendable {
    let subjectID: String
    let tenantID: String
    let companyUID: String
    let companyName: String
    let personUID: String
}

enum HQMessagingMembershipResolver {
    static func resolve(
        subjectID: String,
        response: HQMembershipResponse
    ) -> HQMessagingTenantContext? {
        nil
    }
}

import XCTest
@testable import HQIOS

final class HQProductionMessagingRootTests: XCTestCase {
    func testMembershipResolverUsesTheMostRecentlyUpdatedActiveTenant() throws {
        let response = try HQDomainJSONDecoder().decode(
            HQMembershipResponse.self,
            from: Data(
                #"{"memberships":[{"schemaVersion":1,"role":"member","updatedAt":"2026-09-03T10:00:00Z","acceptedAt":"2026-08-01T10:00:00Z","invitedAt":"2026-07-31T10:00:00Z","companyUid":"cmp_first","invitationId":"inv_first","createdAt":"2026-07-31T10:00:00Z","membershipKey":"key_first","invitedBy":"admin","status":"active","personUid":"prs_first","companyName":"First Co","companySlug":"first","bucketName":"first-bucket","fleetEnabled":false,"teamPlanEnabled":true,"brandingEnabled":false},{"schemaVersion":1,"role":"admin","updatedAt":"2026-09-04T10:00:00Z","acceptedAt":"2026-08-02T10:00:00Z","invitedAt":"2026-08-01T10:00:00Z","companyUid":"cmp_indigo","invitationId":"inv_indigo","createdAt":"2026-08-01T10:00:00Z","membershipKey":"key_indigo","invitedBy":"admin","status":"active","personUid":"prs_me","companyName":"Indigo","companySlug":"indigo","bucketName":"indigo-bucket","fleetEnabled":true,"teamPlanEnabled":true,"brandingEnabled":true},{"schemaVersion":1,"role":"owner","updatedAt":"2026-09-05T10:00:00Z","acceptedAt":"2026-08-03T10:00:00Z","invitedAt":"2026-08-02T10:00:00Z","companyUid":"cmp_revoked","invitationId":"inv_revoked","createdAt":"2026-08-02T10:00:00Z","membershipKey":"key_revoked","invitedBy":"admin","status":"revoked","personUid":"prs_revoked","companyName":"Revoked Co","companySlug":"revoked","bucketName":"revoked-bucket","fleetEnabled":false,"teamPlanEnabled":false,"brandingEnabled":false}]}"#.utf8
            )
        )

        XCTAssertEqual(
            HQMessagingMembershipResolver.resolve(subjectID: "subject-1", response: response),
            HQMessagingTenantContext(
                subjectID: "subject-1",
                tenantID: "cmp_indigo",
                companyUID: "cmp_indigo",
                companyName: "Indigo",
                personUID: "prs_me"
            )
        )
    }

    func testMembershipResolverRejectsEmptySubjectOrNoActiveMembership() throws {
        let response = try HQDomainJSONDecoder().decode(
            HQMembershipResponse.self,
            from: Data(#"{"memberships":[]}"#.utf8)
        )

        XCTAssertNil(HQMessagingMembershipResolver.resolve(subjectID: "", response: response))
        XCTAssertNil(HQMessagingMembershipResolver.resolve(subjectID: "subject-1", response: response))
    }
}

