+@MainActor
+enum HQProductionMessagingFactory {
+    static func make(subjectID: String, session: HQSessionController) -> HQProductionMessagingRuntime {
+        do {
+            let coreAPI = try HQAPIClient(session: session)
+            let messagingAPI = try HQMessagingAPI(session: session)
+            let controller = HQMessagingLiveController(
+                dataSource: HQMessagingAPIDataSource(api: messagingAPI)
+            )
+
+            return HQProductionMessagingRuntime(
+                subjectID: subjectID,
+                liveController: controller,
+                membershipLoader: {
+                    switch try await coreAPI.membership() {
+                    case let .content(response): response
+                    case .degraded, .unavailable:
+                        throw HQAPIClientError.invalidContract("membership-me")
+                    }
+                },
+                messageSender: { conversationID, submission, context in
+                    let attachments = try wireAttachments(
+                        submission.draft.attachments,
+                        context: context
+                    )
+                    switch conversationID {
+                    case let .channel(channelID):
+                        try await messagingAPI.sendChannelMessage(
+                            channelID: channelID,
+                            body: submission.draft.text,
+                            attachments: attachments
+                        )
+                    case let .directMessage(personUID):
+                        _ = try await messagingAPI.sendDM(
+                            to: .personUID(personUID),
+                            body: submission.draft.text,
+                            attachments: attachments
+                        )
+                    }
+                },
+                conversationCreator: { draft, context in
+                    let value = draft.nameOrRecipient.trimmingCharacters(in: .whitespacesAndNewlines)
+                    switch draft.kind {
+                    case .channel:
+                        _ = try await messagingAPI.createChannel(
+                            name: value,
+                            scope: .company,
+                            companyUID: context.companyUID
+                        )
+                    case .group:
+                        let participants = value
+                            .split(separator: ",")
+                            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
+                            .filter { !$0.isEmpty }
+                        _ = try await messagingAPI.createGroupDM(participantUIDs: participants)
+                    case .directMessage:
+                        throw HQMessagingAPIError.invalidArgument(
+                            "Choose an existing person from the conversation directory."
+                        )
+                    }
+                }
+            )
+        } catch {
+            let source = HQUnavailableMessagingDataSource(error: error)
+            return HQProductionMessagingRuntime(
+                subjectID: subjectID,
+                liveController: HQMessagingLiveController(dataSource: source),
+                membershipLoader: { throw error }
+            )
+        }
+    }
+
+    private static func wireAttachments(
+        _ pending: [HQMessagePendingAttachment],
+        context: HQMessagingTenantContext
+    ) throws -> [HQMessagingAttachment] {
+        try pending.map { attachment in
+            guard attachment.id.hasPrefix("vault:"), attachment.id.count > 6 else {
+                throw HQMessagingRuntimeError.attachmentRequiresUpload
+            }
+            return HQMessagingAttachment(
+                id: String(attachment.id.dropFirst(6)),
+                vaultPath: String(attachment.id.dropFirst(6)),
+                companyUID: context.companyUID,
+                name: attachment.name,
+                contentType: attachment.contentType,
+                sizeBytes: attachment.sizeBytes,
+                kind: attachment.kind.rawValue,
+                previewURL: nil
+            )
+        }
+    }
+}
