+    private func importFiles(_ result: Result<[URL], Error>) {
+        switch result {
+        case let .success(urls):
+            Task {
+                for url in urls.prefix(HQMessageComposerPolicy.maximumAttachmentCount) {
+                    let accessing = url.startAccessingSecurityScopedResource()
+                    defer { if accessing { url.stopAccessingSecurityScopedResource() } }
+                    do {
+                        let values = try url.resourceValues(forKeys: [.fileSizeKey, .contentTypeKey])
+                        if let size = values.fileSize,
+                           size > HQMessageComposerPolicy.maximumAttachmentBytes {
+                            throw HQMessageAttachmentRejection.tooLarge(
+                                name: url.lastPathComponent,
+                                maximumBytes: HQMessageComposerPolicy.maximumAttachmentBytes
+                            )
+                        }
+                        let data = try Data(contentsOf: url, options: .mappedIfSafe)
+                        let contentType = values.contentType?.preferredMIMEType
+                            ?? UTType(filenameExtension: url.pathExtension)?.preferredMIMEType
+                            ?? "application/octet-stream"
+                        try await attach(
+                            HQMessagingAttachmentUpload(
+                                data: data,
+                                name: url.lastPathComponent,
+                                contentType: contentType,
+                                kind: contentType.hasPrefix("image/") ? .image : .file
+                            )
+                        )
+                    } catch {
+                        presentAttachmentError(error)
+                        break
+                    }
+                }
+            }
+        case let .failure(error):
+            presentAttachmentError(error)
+        }
+    }
+
+    private func importPhotos(_ items: [PhotosPickerItem]) async {
+        defer { photoSelection = [] }
+        for (index, item) in items.enumerated() {
+            do {
+                guard let data = try await item.loadTransferable(type: Data.self) else {
+                    throw HQMessagingAPIError.invalidResponse("photo-import")
+                }
+                let type = item.supportedContentTypes.first ?? .jpeg
+                let contentType = type.preferredMIMEType ?? "image/jpeg"
+                let fileExtension = type.preferredFilenameExtension ?? "jpg"
+                try await attach(
+                    HQMessagingAttachmentUpload(
+                        data: data,
+                        name: "photo-\(index + 1).\(fileExtension)",
+                        contentType: contentType,
+                        kind: .image
+                    )
+                )
+            } catch {
+                presentAttachmentError(error)
+                break
+            }
+        }
+    }
