+    ) throws -> HQMessagingProjectFilePreviewKind? {
+        guard action == .preview else { return nil }
+        let normalized = HQMessagingProjectFileTransportPolicy.normalizedContentType(contentType)
+        if HQMessagingProjectFileTransportPolicy.safeImageContentTypes.contains(normalized) {
+            return .image
+        }
+        if normalized == "application/pdf" {
+            return .pdf
+        }
+        let fileExtension = safeFileExtension(vaultPath)
+        let isText = normalized.hasPrefix("text/")
+            || normalized == "application/json"
+            || ["md", "markdown", "txt", "json", "csv", "log"].contains(fileExtension)
+        guard isText else {
+            throw HQMessagingProjectFileActionError.unsupportedPreviewType
+        }
+        guard String(data: data, encoding: .utf8) != nil else {
+            throw HQMessagingProjectFileActionError.invalidPreviewText
+        }
+        return .text
