+enum HQMessagingProjectFileTransportPolicy {
+    static let safeImageContentTypes: Set<String> = [
+        "image/png",
+        "image/jpeg",
+        "image/gif",
+        "image/webp",
+        "image/avif",
+    ]
+
+    static func hardenedConfiguration(
+        basedOn base: URLSessionConfiguration = .ephemeral
+    ) -> URLSessionConfiguration {
+        let configuration = (base.copy() as? URLSessionConfiguration) ?? .ephemeral
+        configuration.urlCache = nil
+        configuration.httpCookieStorage = nil
+        configuration.urlCredentialStorage = nil
+        configuration.httpShouldSetCookies = false
+        configuration.httpCookieAcceptPolicy = .never
+        configuration.requestCachePolicy = .reloadIgnoringLocalCacheData
+        return configuration
+    }
+
+    static func allowsRedirect(from source: URL, to destination: URL) -> Bool {
+        guard let source = origin(source), let destination = origin(destination) else {
+            return false
+        }
+        return source == destination
+    }
+
+    static func normalizedContentType(_ value: String?) -> String {
+        (value ?? "")
+            .split(separator: ";", maxSplits: 1, omittingEmptySubsequences: true)
+            .first
+            .map(String.init)?
+            .trimmingCharacters(in: .whitespacesAndNewlines)
+            .lowercased() ?? ""
+    }
+
+    private static func origin(_ url: URL) -> String? {
+        guard let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
+              components.scheme?.lowercased() == "https",
+              let host = components.host?.lowercased(),
+              !host.isEmpty,
+              components.user == nil,
+              components.password == nil,
+              components.fragment == nil,
+              components.port == nil || components.port == 443 else {
+            return nil
+        }
+        return "https://\(host):\(components.port ?? 443)"
+    }
+}
