+private final class HQMessagingProjectFileLiveTransport: NSObject, URLSessionDataDelegate, @unchecked Sendable {
+    private let sourceURL: URL
+    private let maximumBytes: Int
+    private let configuration: URLSessionConfiguration
+    private let lock = NSLock()
+    private var accumulator: HQMessagingProjectFileDownloadAccumulator
+    private var continuation: CheckedContinuation<HQMessagingProjectFileDownload, Error>?
+    private var task: URLSessionDataTask?
+    private var session: URLSession?
+    private var responseURL: URL?
+    private var statusCode: Int?
+    private var contentType: String?
