+              request.httpMethod?.uppercased() == "PUT" else {
+            throw HQMessagingProjectFileActionError.invalidPresignedURL
+        }
+        let delegate = HQMessagingNoUploadRedirectDelegate(sourceURL: sourceURL)
+        let session = URLSession(
+            configuration: HQMessagingProjectFileTransportPolicy.hardenedConfiguration(
+                basedOn: configuration
+            ),
+            delegate: delegate,
+            delegateQueue: nil
+        )
+        defer { session.finishTasksAndInvalidate() }
+        var safeRequest = request
+        safeRequest.cachePolicy = .reloadIgnoringLocalCacheData
+        safeRequest.httpShouldHandleCookies = false
