+        let response: URLResponse
+        do {
+            (_, response) = try await session.upload(for: safeRequest, from: data)
+        } catch {
+            if delegate.rejectedRedirect {
+                throw HQMessagingProjectFileActionError.foreignDownloadURL
+            }
+            throw HQMessagingProjectFileActionError.downloadFailed
+        }
+        if delegate.rejectedRedirect {
+            throw HQMessagingProjectFileActionError.foreignDownloadURL
+        }
+        guard let http = response as? HTTPURLResponse,
+              let responseURL = http.url else {
+            throw HQMessagingProjectFileActionError.downloadFailed
+        }
+        guard HQMessagingProjectFileTransportPolicy.allowsRedirect(
+            from: sourceURL,
