+private enum HQSafeMessageMarkdown {
+    static func attributed(_ value: String) -> AttributedString {
+        let options = AttributedString.MarkdownParsingOptions(
+            interpretedSyntax: .inlineOnlyPreservingWhitespace,
+            failurePolicy: .returnPartiallyParsedIfPossible
+        )
+        guard var attributed = try? AttributedString(markdown: value, options: options) else {
+            return AttributedString(value)
+        }
+        let unsafeLinks = attributed.runs.compactMap { run -> Range<AttributedString.Index>? in
+            guard let link = run.link,
+                  !["https", "http"].contains(link.scheme?.lowercased() ?? "") else {
+                return nil
+            }
+            return run.range
+        }
+        for range in unsafeLinks { attributed[range].link = nil }
+        return attributed
+    }
+}
