import Foundation
import XCTest
@testable import HQIOS

@MainActor
final class HQMessagingMentionDirectoryTests: XCTestCase {
    func testAgentRosterAcceptsCurrentEnvelopeAndLegacyBareRowsWithoutInventingIdentity() throws {
        let envelope = try decode(
            HQMessagingAgentRosterResponse.self,
            #"{"agents":[{"uid":"agt_izzy","displayName":"Izzy","description":"Fleet","companyUid":"cmp_indigo","status":"ready"}]}"#
        )
        XCTAssertEqual(envelope.agents, [
            .init(
                agentUID: "agt_izzy",
                displayName: "Izzy",
                description: "Fleet",
                companyUID: "cmp_indigo",
                status: "ready"
            ),
        ])

        let bare = try decode(
            HQMessagingAgentRosterResponse.self,
            #"[{"agentUid":"agt_atlas","name":"Atlas","companyUid":"cmp_indigo"}]"#
        )
        XCTAssertEqual(bare.agents.first?.agentUID, "agt_atlas")
        XCTAssertEqual(bare.agents.first?.displayName, "Atlas")

        XCTAssertThrowsError(
            try decode(HQMessagingAgentRosterResponse.self, #"{"agents":[{"displayName":"Anonymous"}]}"#)
        )
    }

    func testDirectoryCombinesTenantHumansAndAgentsWithExactWireIdentities() throws {
        let contacts = try decode(
            HQMessagingContactsResponse.self,
            #"{"contacts":[{"personUid":"prs_izzy","displayName":"Izzy","email":"izzy@example.com","companyUid":"cmp_indigo"},{"personUid":"prs_self","displayName":"Corey","email":"corey@example.com","companyUid":"cmp_indigo"},{"personUid":"prs_other","displayName":"Other","email":"other@example.com","companyUid":"cmp_other"}]}"#
        )
        let roster = try decode(
            HQMessagingAgentRosterResponse.self,
            #"{"agents":[{"uid":"agt_izzy","displayName":"Izzy","companyUid":"cmp_indigo"},{"uid":"agt_other","displayName":"Wrong tenant","companyUid":"cmp_other"}]}"#
        )

        let candidates = HQMessagingMentionDirectory.makeCandidates(
            contacts: contacts.contacts,
            agents: roster.agents,
            companyUID: "cmp_indigo",
            companyName: "Indigo",
            excludingPersonUID: "prs_self"
        )

        XCTAssertEqual(candidates.map(\.participantUID), ["agt_izzy", "prs_izzy"])
        XCTAssertEqual(candidates.map(\.participantType), [.agent, .human])
        XCTAssertEqual(candidates.map(\.disambiguator), ["Indigo", "izzy@example.com"])
        XCTAssertEqual(candidates.map(\.wireMention), [
            .init(participantUID: "agt_izzy", participantType: .agent, displayName: "Izzy", email: nil),
            .init(participantUID: "prs_izzy", participantType: .human, displayName: "Izzy", email: "izzy@example.com"),
        ])
    }

    private func decode<Value: Decodable>(_ type: Value.Type, _ json: String) throws -> Value {
        try HQDomainJSONDecoder().decode(type, from: Data(json.utf8))
    }
}

