import Foundation

struct HQMessagingAgentRosterEntry: Decodable, Equatable, Hashable, Sendable {
    let agentUID: String
    let displayName: String
    let description: String?
    let companyUID: String?
    let status: String?

    enum CodingKeys: String, CodingKey {
        case agentUID = "agentUid"
        case uid
        case displayName
        case name
        case description
        case companyUID = "companyUid"
        case status
    }

    init(
        agentUID: String,
        displayName: String,
        description: String? = nil,
        companyUID: String? = nil,
        status: String? = nil
    ) {
        self.agentUID = agentUID
        self.displayName = displayName
        self.description = description
        self.companyUID = companyUID
        self.status = status
    }

    init(from decoder: Decoder) throws {
        let values = try decoder.container(keyedBy: CodingKeys.self)
        let agentUID = try values.decodeIfPresent(String.self, forKey: .agentUID)
            ?? values.decodeIfPresent(String.self, forKey: .uid)
        let displayName = try values.decodeIfPresent(String.self, forKey: .displayName)
            ?? values.decodeIfPresent(String.self, forKey: .name)
        guard let agentUID = Self.nonempty(agentUID) else {
            throw DecodingError.dataCorruptedError(
                forKey: .agentUID,
                in: values,
                debugDescription: "An agent roster row requires agentUid or uid."
            )
        }
        self.agentUID = agentUID
        self.displayName = Self.nonempty(displayName) ?? agentUID
        description = Self.nonempty(try values.decodeIfPresent(String.self, forKey: .description))
        companyUID = Self.nonempty(try values.decodeIfPresent(String.self, forKey: .companyUID))
        status = Self.nonempty(try values.decodeIfPresent(String.self, forKey: .status))
    }

    private static func nonempty(_ value: String?) -> String? {
        guard let value else { return nil }
        let cleaned = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return cleaned.isEmpty ? nil : cleaned
    }
}

struct HQMessagingAgentRosterResponse: Decodable, Equatable, Sendable {
    let agents: [HQMessagingAgentRosterEntry]

    enum CodingKeys: String, CodingKey { case agents }

    init(from decoder: Decoder) throws {
        if let bare = try? decoder.singleValueContainer().decode([HQMessagingAgentRosterEntry].self) {
            agents = bare
            return
        }
        let values = try decoder.container(keyedBy: CodingKeys.self)
        agents = try values.decode([HQMessagingAgentRosterEntry].self, forKey: .agents)
    }
}

enum HQMessagingMentionDirectory {
    static func makeCandidates(
        contacts: [HQMessagingContact],
        agents: [HQMessagingAgentRosterEntry],
        companyUID: String,
        companyName: String,
        excludingPersonUID: String
    ) -> [HQMessageMentionCandidate] {
        let tenantID = clean(companyUID)
        let excludedID = clean(excludingPersonUID)
        let readableCompanyName = nonempty(companyName)

        let humans = contacts.compactMap { contact -> HQMessageMentionCandidate? in
            let personUID = clean(contact.personUID)
            let contactCompanyUID = nonempty(contact.companyUID)
            guard !personUID.isEmpty,
                  personUID != excludedID,
                  contactCompanyUID == nil || contactCompanyUID == tenantID
            else { return nil }
            return HQMessageMentionCandidate(
                participantUID: personUID,
                participantType: .human,
                displayName: readableName(contact.displayName, fallback: contact.email, id: personUID),
                email: nonempty(contact.email),
                companyUID: contactCompanyUID ?? tenantID,
                companyName: readableCompanyName
            )
        }

        let fleet = agents.compactMap { agent -> HQMessageMentionCandidate? in
            let agentUID = clean(agent.agentUID)
            let agentCompanyUID = nonempty(agent.companyUID)
            guard !agentUID.isEmpty,
                  agentCompanyUID == nil || agentCompanyUID == tenantID
            else { return nil }
            return HQMessageMentionCandidate(
                participantUID: agentUID,
                participantType: .agent,
                displayName: readableName(agent.displayName, fallback: nil, id: agentUID),
                companyUID: agentCompanyUID ?? tenantID,
                companyName: readableCompanyName
            )
        }

        return HQMessageMentionEngine.normalize(humans + fleet)
    }

    private static func readableName(_ primary: String, fallback: String?, id: String) -> String {
        nonempty(primary) ?? nonempty(fallback) ?? id
    }

    private static func nonempty(_ value: String?) -> String? {
        guard let value else { return nil }
        let cleaned = clean(value)
        return cleaned.isEmpty ? nil : cleaned
    }

    private static func clean(_ value: String) -> String {
        value.trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

