import Foundation
import XCTest
@testable import HQIOS

@MainActor
final class HQBackgroundContractTests: XCTestCase {
    func testAPNsTokenUsesCanonicalLowercaseHexAndRejectsEmptyOrOversizedValues() {
        XCTAssertEqual(
            HQAPNsDeviceToken.canonicalHex(Data([0x00, 0x0A, 0xF1, 0xFF])),
            "000af1ff"
        )
        XCTAssertNil(HQAPNsDeviceToken.canonicalHex(Data()))
        XCTAssertNil(HQAPNsDeviceToken.canonicalHex(Data(repeating: 0x01, count: 129)))
    }

    func testPushCoordinatorRegistersOnlyAfterAuthorizationIdentityMembershipAndToken() async throws {
        let store = HQPushMemoryStateStore(
            initial: HQPushPersistedState(deviceID: "dev_fixed")
        )
        let service = HQPushRecordingService()
        let coordinator = HQPushCoordinator(
            stateStore: store,
            registrationService: service,
            previewMode: .generic
        )

        await coordinator.authenticationDidChange(.signedIn(subjectID: "prs_owner"))
        await coordinator.membershipDidChange(subjectID: "prs_owner", tenantID: "cmp_indigo")
        XCTAssertTrue(service.registrations.isEmpty)

        await coordinator.authorizationDidChange(isAuthorized: true)
        XCTAssertTrue(service.registrations.isEmpty)

        await coordinator.receiveDeviceToken(Data([0x01, 0xAB, 0xFF]))

        XCTAssertEqual(
            service.registrations,
            [
                HQPushRegistrationRequest(
                    deviceID: "dev_fixed",
                    platform: "apns",
                    deviceToken: "01abff",
                    preview: .generic
                )
            ]
        )
        XCTAssertEqual(service.removals, [])
        let persisted = try await XCTUnwrap(store.load())
        XCTAssertEqual(persisted.registeredOwnerSubjectID, "prs_owner")
        XCTAssertNotNil(persisted.registeredTokenFingerprint)
        XCTAssertNil(persisted.pendingRemovalOwnerSubjectID)
    }

    func testTokenRotationReregistersButDuplicateDeliveryIsIdempotent() async {
        let store = HQPushMemoryStateStore(initial: .init(deviceID: "dev_fixed"))
        let service = HQPushRecordingService()
        let coordinator = HQPushCoordinator(
            stateStore: store,
            registrationService: service,
            previewMode: .sender
        )

        await coordinator.authenticationDidChange(.signedIn(subjectID: "prs_owner"))
        await coordinator.membershipDidChange(subjectID: "prs_owner", tenantID: "cmp_indigo")
        await coordinator.authorizationDidChange(isAuthorized: true)
        await coordinator.receiveDeviceToken(Data([0x10]))
        await coordinator.receiveDeviceToken(Data([0x10]))
        await coordinator.receiveDeviceToken(Data([0x11]))

        XCTAssertEqual(service.registrations.map(\.deviceToken), ["10", "11"])
        XCTAssertEqual(service.registrations.map(\.preview), [.sender, .sender])
    }

    func testSignOutRemovesRegistrationAndPurgesOwnerAndTokenFingerprint() async throws {
        let store = HQPushMemoryStateStore(initial: .init(deviceID: "dev_fixed"))
        let service = HQPushRecordingService()
        let coordinator = HQPushCoordinator(
            stateStore: store,
            registrationService: service
        )
        await activate(coordinator)

        await coordinator.prepareForSignOut()

        XCTAssertEqual(service.removals, ["dev_fixed"])
        let persisted = try await XCTUnwrap(store.load())
        XCTAssertNil(persisted.registeredOwnerSubjectID)
        XCTAssertNil(persisted.registeredTokenFingerprint)
        XCTAssertNil(persisted.pendingRemovalOwnerSubjectID)
        XCTAssertEqual(persisted.deviceID, "dev_fixed", "The nonsecret stable device identity survives sign-out")
    }

    func testFailedRemovalPersistsSafeRetryAndSameOwnerDrainsItBeforeRegistering() async throws {
        let store = HQPushMemoryStateStore(initial: .init(deviceID: "dev_fixed"))
        let service = HQPushRecordingService()
        let coordinator = HQPushCoordinator(
            stateStore: store,
            registrationService: service
        )
        await activate(coordinator)
        service.failRemoval = true

        await coordinator.prepareForSignOut()

        var persisted = try await XCTUnwrap(store.load())
        XCTAssertEqual(persisted.pendingRemovalOwnerSubjectID, "prs_owner")
        XCTAssertEqual(persisted.pendingRemovalDeviceID, "dev_fixed")
        XCTAssertNil(persisted.registeredTokenFingerprint)

        service.failRemoval = false
        service.events = []
        await activate(coordinator, token: Data([0x22]))

        XCTAssertEqual(service.events, ["remove:dev_fixed", "register:22"])
        persisted = try await XCTUnwrap(store.load())
        XCTAssertNil(persisted.pendingRemovalOwnerSubjectID)
        XCTAssertEqual(persisted.registeredOwnerSubjectID, "prs_owner")
    }

    func testMembershipLossAttemptsRemovalAndLeavesNoProtectedRegistrationState() async throws {
        let store = HQPushMemoryStateStore(initial: .init(deviceID: "dev_fixed"))
        let service = HQPushRecordingService()
        let coordinator = HQPushCoordinator(
            stateStore: store,
            registrationService: service
        )
        await activate(coordinator)

        await coordinator.membershipDidChange(subjectID: "prs_owner", tenantID: nil)

        XCTAssertEqual(service.removals, ["dev_fixed"])
        let persisted = try await XCTUnwrap(store.load())
        XCTAssertNil(persisted.registeredOwnerSubjectID)
        XCTAssertNil(persisted.registeredTokenFingerprint)
    }

    func testWidgetCacheIsSubjectScopedAndCannotEncodeMessageContent() throws {
        let suite = "HQBackgroundContractTests.\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: suite))
        defer { defaults.removePersistentDomain(forName: suite) }
        let store = HQWidgetSharedCache(defaults: defaults, key: "snapshot")
        let now = Date(timeIntervalSince1970: 1_788_470_400)

        try store.save(
            .unread(
                ownerFingerprint: "owner_fingerprint",
                unreadCount: 7,
                updatedAt: now,
                isOffline: false
            )
        )

        XCTAssertEqual(try store.load()?.unreadCount, 7)
        XCTAssertEqual(try store.load()?.presentation, .unread)
        let raw = try XCTUnwrap(defaults.data(forKey: "snapshot"))
        let serialized = try XCTUnwrap(String(data: raw, encoding: .utf8))
        XCTAssertFalse(serialized.contains("message"))
        XCTAssertFalse(serialized.contains("body"))
        XCTAssertFalse(serialized.contains("sender"))
        XCTAssertFalse(serialized.contains("tenant"))
        XCTAssertEqual(HQWidgetSharedCache.inboxURL.absoluteString, "hqmobile://route/inbox")
    }

    func testWidgetStatesCoverSignedOutEmptyStaleAndUnread() {
        let now = Date(timeIntervalSince1970: 1_788_470_400)
        XCTAssertEqual(HQWidgetSnapshot.signedOut(updatedAt: now).presentation, .signedOut)
        XCTAssertEqual(
            HQWidgetSnapshot.empty(ownerFingerprint: "owner", updatedAt: now).presentation,
            .empty
        )
        XCTAssertEqual(
            HQWidgetSnapshot.unread(
                ownerFingerprint: "owner",
                unreadCount: 0,
                updatedAt: now,
                isOffline: true
            ).presentation,
            .staleOffline
        )
        XCTAssertEqual(
            HQWidgetSnapshot.unread(
                ownerFingerprint: "owner",
                unreadCount: 2,
                updatedAt: now,
                isOffline: false
            ).presentation,
            .unread
        )
    }

    private func activate(
        _ coordinator: HQPushCoordinator,
        token: Data = Data([0x21])
    ) async {
        await coordinator.authenticationDidChange(.signedIn(subjectID: "prs_owner"))
        await coordinator.membershipDidChange(subjectID: "prs_owner", tenantID: "cmp_indigo")
        await coordinator.authorizationDidChange(isAuthorized: true)
        await coordinator.receiveDeviceToken(token)
    }
}

private enum HQPushTestFailure: Error {
    case removal
}

@MainActor
private final class HQPushRecordingService: HQPushRegistrationServicing {
    var registrations: [HQPushRegistrationRequest] = []
    var removals: [String] = []
    var events: [String] = []
    var failRemoval = false

    func register(_ request: HQPushRegistrationRequest) async throws {
        registrations.append(request)
        events.append("register:\(request.deviceToken)")
    }

    func remove(deviceID: String) async throws {
        removals.append(deviceID)
        events.append("remove:\(deviceID)")
        if failRemoval { throw HQPushTestFailure.removal }
    }
}

private actor HQPushMemoryStateStore: HQPushStateStoring {
    private var state: HQPushPersistedState?

    init(initial: HQPushPersistedState?) {
        state = initial
    }

    func load() -> HQPushPersistedState? { state }
    func save(_ state: HQPushPersistedState) { self.state = state }
}

import CryptoKit
import Foundation

enum HQWidgetPresentation: String, Codable, Equatable, Sendable {
    case signedOut
    case empty
    case staleOffline
    case unread
}

/// Deliberately excludes tenant IDs, people, channel names, message IDs, and
/// bodies. The owner is one-way hashed so widgets cannot cross account state.
struct HQWidgetSnapshot: Codable, Equatable, Sendable {
    let ownerFingerprint: String?
    let unreadCount: Int
    let updatedAt: Date
    let isOffline: Bool

    var presentation: HQWidgetPresentation {
        guard ownerFingerprint != nil else { return .signedOut }
        if isOffline { return .staleOffline }
        return unreadCount > 0 ? .unread : .empty
    }

    static func signedOut(updatedAt: Date = .now) -> Self {
        Self(ownerFingerprint: nil, unreadCount: 0, updatedAt: updatedAt, isOffline: false)
    }

    static func empty(ownerFingerprint: String, updatedAt: Date = .now) -> Self {
        Self(ownerFingerprint: ownerFingerprint, unreadCount: 0, updatedAt: updatedAt, isOffline: false)
    }

    static func unread(
        ownerFingerprint: String,
        unreadCount: Int,
        updatedAt: Date = .now,
        isOffline: Bool
    ) -> Self {
        Self(
            ownerFingerprint: ownerFingerprint,
            unreadCount: max(0, unreadCount),
            updatedAt: updatedAt,
            isOffline: isOffline
        )
    }

    static func ownerFingerprint(_ subjectID: String) -> String {
        SHA256.hash(data: Data(subjectID.utf8)).map { String(format: "%02x", $0) }.joined()
    }
}

struct HQWidgetSharedCache: Sendable {
    static let appGroup = "group.com.hqforwork.mobile"
    static let defaultKey = "hq.widget.snapshot.v1"
    static let inboxURL = URL(string: "hqmobile://route/inbox")!

    private let defaults: UserDefaults
    private let key: String

    init?(
        suiteName: String = appGroup,
        key: String = defaultKey
    ) {
        guard let defaults = UserDefaults(suiteName: suiteName) else { return nil }
        self.defaults = defaults
        self.key = key
    }

    init(defaults: UserDefaults, key: String = defaultKey) {
        self.defaults = defaults
        self.key = key
    }

    func load() throws -> HQWidgetSnapshot? {
        guard let data = defaults.data(forKey: key) else { return nil }
        let snapshot = try JSONDecoder().decode(HQWidgetSnapshot.self, from: data)
        guard snapshot.unreadCount >= 0,
              snapshot.ownerFingerprint.map(Self.isFingerprint) ?? true
        else { throw HQWidgetCacheError.corrupt }
        return snapshot
    }

    func save(_ snapshot: HQWidgetSnapshot) throws {
        guard snapshot.unreadCount >= 0,
              snapshot.ownerFingerprint.map(Self.isFingerprint) ?? true
        else { throw HQWidgetCacheError.corrupt }
        defaults.set(try JSONEncoder().encode(snapshot), forKey: key)
    }

    private static func isFingerprint(_ value: String) -> Bool {
        value.count == 64 && value.allSatisfy { $0.isHexDigit && !$0.isUppercase }
    }
}

enum HQWidgetCacheError: Error, Equatable {
    case corrupt
}

import CryptoKit
import Foundation
import Security
import UIKit
import UserNotifications

enum HQPushPreviewMode: String, Codable, CaseIterable, Equatable, Sendable {
    case generic
    case sender
    case full
}

struct HQPushRegistrationRequest: Codable, Equatable, Sendable {
    let deviceID: String
    let platform: String
    let deviceToken: String
    let preview: HQPushPreviewMode

    init(
        deviceID: String,
        platform: String = "apns",
        deviceToken: String,
        preview: HQPushPreviewMode = .generic
    ) {
        self.deviceID = deviceID
        self.platform = platform
        self.deviceToken = deviceToken
        self.preview = preview
    }

    private enum CodingKeys: String, CodingKey {
        case deviceID = "deviceId"
        case platform
        case deviceToken
        case preview
    }
}

enum HQAPNsDeviceToken {
    static let maximumBytes = 128

    static func canonicalHex(_ data: Data) -> String? {
        guard !data.isEmpty, data.count <= maximumBytes else { return nil }
        return data.map { String(format: "%02x", $0) }.joined()
    }
}

@MainActor
protocol HQPushRegistrationServicing: AnyObject {
    func register(_ request: HQPushRegistrationRequest) async throws
    func remove(deviceID: String) async throws
}

extension HQMessagingAPI: HQPushRegistrationServicing {
    func register(_ request: HQPushRegistrationRequest) async throws {
        try await registerPushDevice(request)
    }

    func remove(deviceID: String) async throws {
        try await removePushDevice(deviceID: deviceID)
    }
}

struct HQPushPersistedState: Codable, Equatable, Sendable {
    let deviceID: String
    var registeredOwnerSubjectID: String?
    var registeredTokenFingerprint: String?
    var registeredPreview: HQPushPreviewMode?
    var pendingRemovalOwnerSubjectID: String?
    var pendingRemovalDeviceID: String?

    init(
        deviceID: String,
        registeredOwnerSubjectID: String? = nil,
        registeredTokenFingerprint: String? = nil,
        registeredPreview: HQPushPreviewMode? = nil,
        pendingRemovalOwnerSubjectID: String? = nil,
        pendingRemovalDeviceID: String? = nil
    ) {
        self.deviceID = deviceID
        self.registeredOwnerSubjectID = registeredOwnerSubjectID
        self.registeredTokenFingerprint = registeredTokenFingerprint
        self.registeredPreview = registeredPreview
        self.pendingRemovalOwnerSubjectID = pendingRemovalOwnerSubjectID
        self.pendingRemovalDeviceID = pendingRemovalDeviceID
    }
}

protocol HQPushStateStoring: Sendable {
    func load() async throws -> HQPushPersistedState?
    func save(_ state: HQPushPersistedState) async throws
}

actor HQPushKeychainStateStore: HQPushStateStoring {
    static let service = "com.hqforwork.mobile.push"
    static let account = "device-registration-v1"

    private let security: any HQSecurityAdapting

    init(security: any HQSecurityAdapting = HQSystemSecurityAdapter()) {
        self.security = security
    }

    func load() throws -> HQPushPersistedState? {
        let (status, data) = security.copy(service: Self.service, account: Self.account)
        if status == errSecItemNotFound { return nil }
        try HQKeychainTokenStore.validate(status)
        guard let data,
              let state = try? JSONDecoder().decode(HQPushPersistedState.self, from: data),
              Self.isValid(state)
        else { throw HQKeychainTokenStoreError.corrupt }
        return state
    }

    func save(_ state: HQPushPersistedState) throws {
        guard Self.isValid(state) else { throw HQKeychainTokenStoreError.corrupt }
        let data = try JSONEncoder().encode(state)
        let accessibility = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly
        let status = security.add(
            service: Self.service,
            account: Self.account,
            data: data,
            accessibility: accessibility,
            synchronizable: false
        )
        if status == errSecDuplicateItem {
            let update = security.update(
                service: Self.service,
                account: Self.account,
                data: data,
                accessibility: accessibility,
                synchronizable: false
            )
            try HQKeychainTokenStore.validate(update)
        } else {
            try HQKeychainTokenStore.validate(status)
        }
    }

    private static func isValid(_ state: HQPushPersistedState) -> Bool {
        guard isIdentifier(state.deviceID) else { return false }
        let optionalIdentifiers = [
            state.registeredOwnerSubjectID,
            state.pendingRemovalOwnerSubjectID,
            state.pendingRemovalDeviceID,
        ]
        guard optionalIdentifiers.compactMap({ $0 }).allSatisfy(isIdentifier) else { return false }
        if let fingerprint = state.registeredTokenFingerprint {
            guard fingerprint.count == 64,
                  fingerprint.allSatisfy({ $0.isHexDigit && !$0.isUppercase })
            else { return false }
        }
        guard (state.pendingRemovalOwnerSubjectID == nil)
                == (state.pendingRemovalDeviceID == nil)
        else { return false }
        return true
    }

    private static func isIdentifier(_ value: String) -> Bool {
        !value.isEmpty
            && value.utf8.count <= 128
            && value.unicodeScalars.allSatisfy {
                CharacterSet.alphanumerics.contains($0) || $0 == "_" || $0 == "-"
            }
    }
}

@MainActor
protocol HQPushSystemControlling: AnyObject {
    func authorizationStatus() async -> UNAuthorizationStatus
    func requestAuthorization() async throws -> Bool
    func registerForRemoteNotifications()
}

@MainActor
final class HQPushSystemController: HQPushSystemControlling {
    func authorizationStatus() async -> UNAuthorizationStatus {
        await UNUserNotificationCenter.current().notificationSettings().authorizationStatus
    }

    func requestAuthorization() async throws -> Bool {
        try await UNUserNotificationCenter.current().requestAuthorization(
            options: [.alert, .badge, .sound]
        )
    }

    func registerForRemoteNotifications() {
        UIApplication.shared.registerForRemoteNotifications()
    }
}

/// Owns the APNs registration lifecycle. Only opaque identity, a stable device
/// identifier, and a token fingerprint persist; message previews and payload
/// content never cross this boundary.
@MainActor
final class HQPushCoordinator {
    private let stateStore: any HQPushStateStoring
    private let registrationService: any HQPushRegistrationServicing
    private let system: (any HQPushSystemControlling)?
    private let previewMode: HQPushPreviewMode

    private var persistedState: HQPushPersistedState?
    private var activeSubjectID: String?
    private var activeTenantID: String?
    private var tokenHex: String?
    private var isAuthorized = false
    private var permissionRequestInFlight = false

    init(
        stateStore: any HQPushStateStoring = HQPushKeychainStateStore(),
        registrationService: any HQPushRegistrationServicing,
        system: (any HQPushSystemControlling)? = nil,
        previewMode: HQPushPreviewMode = .generic
    ) {
        self.stateStore = stateStore
        self.registrationService = registrationService
        self.system = system
        self.previewMode = previewMode
    }

    func requestAuthorizationIfNeeded() async {
        guard !permissionRequestInFlight, let system else { return }
        permissionRequestInFlight = true
        defer { permissionRequestInFlight = false }

        let status = await system.authorizationStatus()
        switch status {
        case .authorized, .provisional, .ephemeral:
            await authorizationDidChange(isAuthorized: true)
            system.registerForRemoteNotifications()
        case .notDetermined:
            let granted = (try? await system.requestAuthorization()) == true
            await authorizationDidChange(isAuthorized: granted)
            if granted { system.registerForRemoteNotifications() }
        case .denied:
            await authorizationDidChange(isAuthorized: false)
        @unknown default:
            await authorizationDidChange(isAuthorized: false)
        }
    }

    func authenticationDidChange(_ authentication: HQAuthenticationState) async {
        switch authentication {
        case let .signedIn(subjectID):
            activeSubjectID = Self.canonicalIdentifier(subjectID)
            await synchronize()
        case .signedOut, .signingOut, .reauthenticationRequired, .securityResetRequired:
            await removeCurrentRegistration()
            activeSubjectID = nil
            activeTenantID = nil
            tokenHex = nil
        case .restoring, .signingIn:
            break
        }
    }

    func membershipDidChange(subjectID: String?, tenantID: String?) async {
        let subjectID = subjectID.flatMap(Self.canonicalIdentifier)
        let tenantID = tenantID.flatMap(Self.canonicalIdentifier)
        guard subjectID == activeSubjectID else {
            await removeCurrentRegistration()
            activeTenantID = nil
            return
        }
        if activeTenantID != nil, activeTenantID != tenantID {
            await removeCurrentRegistration()
        }
        activeTenantID = tenantID
        await synchronize()
    }

    func authorizationDidChange(isAuthorized: Bool) async {
        if self.isAuthorized, !isAuthorized {
            await removeCurrentRegistration()
        }
        self.isAuthorized = isAuthorized
        await synchronize()
    }

    func receiveDeviceToken(_ data: Data) async {
        guard let canonical = HQAPNsDeviceToken.canonicalHex(data) else { return }
        tokenHex = canonical
        await synchronize()
    }

    func didFailToRegister() {
        tokenHex = nil
    }

    /// Called before credentials are cleared so remote removal can succeed.
    /// Failure is persisted as an identifiers-only retry for the same owner.
    func prepareForSignOut() async {
        await removeCurrentRegistration()
        activeSubjectID = nil
        activeTenantID = nil
        tokenHex = nil
    }

    private func synchronize() async {
        guard let subjectID = activeSubjectID,
              activeTenantID != nil,
              isAuthorized,
              let tokenHex
        else { return }

        do {
            var state = try await loadedState()
            if state.pendingRemovalOwnerSubjectID == subjectID,
               let pendingDeviceID = state.pendingRemovalDeviceID {
                try await registrationService.remove(deviceID: pendingDeviceID)
                state.pendingRemovalOwnerSubjectID = nil
                state.pendingRemovalDeviceID = nil
                try await store(state)
            }

            let fingerprint = Self.fingerprint(tokenHex)
            guard state.registeredOwnerSubjectID != subjectID
                    || state.registeredTokenFingerprint != fingerprint
                    || state.registeredPreview != previewMode
            else { return }

            try await registrationService.register(
                HQPushRegistrationRequest(
                    deviceID: state.deviceID,
                    deviceToken: tokenHex,
                    preview: previewMode
                )
            )
            state.registeredOwnerSubjectID = subjectID
            state.registeredTokenFingerprint = fingerprint
            state.registeredPreview = previewMode
            // A successful stable-device upsert is authoritative for the
            // current owner; retaining an old removal would risk deleting it.
            state.pendingRemovalOwnerSubjectID = nil
            state.pendingRemovalDeviceID = nil
            try await store(state)
        } catch {
            // Registration is opportunistic. The unchanged fingerprint makes
            // the next lifecycle/token event retry without exposing content.
        }
    }

    private func removeCurrentRegistration() async {
        do {
            var state = try await loadedState()
            guard let owner = state.registeredOwnerSubjectID,
                  let activeSubjectID,
                  owner == activeSubjectID
            else { return }

            do {
                try await registrationService.remove(deviceID: state.deviceID)
                state.pendingRemovalOwnerSubjectID = nil
                state.pendingRemovalDeviceID = nil
            } catch {
                state.pendingRemovalOwnerSubjectID = owner
                state.pendingRemovalDeviceID = state.deviceID
            }
            state.registeredOwnerSubjectID = nil
            state.registeredTokenFingerprint = nil
            state.registeredPreview = nil
            try await store(state)
        } catch {
            // Keychain failures fail closed: no new registration is attempted
            // until protected state becomes readable again.
        }
    }

    private func loadedState() async throws -> HQPushPersistedState {
        if let persistedState { return persistedState }
        if let stored = try await stateStore.load() {
            persistedState = stored
            return stored
        }
        let created = HQPushPersistedState(deviceID: UUID().uuidString.lowercased())
        try await stateStore.save(created)
        persistedState = created
        return created
    }

    private func store(_ state: HQPushPersistedState) async throws {
        try await stateStore.save(state)
        persistedState = state
    }

    private static func fingerprint(_ token: String) -> String {
        SHA256.hash(data: Data(token.utf8)).map { String(format: "%02x", $0) }.joined()
    }

    private static func canonicalIdentifier(_ value: String) -> String? {
        guard !value.isEmpty,
              value == value.trimmingCharacters(in: .whitespacesAndNewlines),
              value.utf8.count <= 128,
              value.unicodeScalars.allSatisfy({
                  CharacterSet.alphanumerics.contains($0) || $0 == "_" || $0 == "-"
              })
        else { return nil }
        return value
    }
}

/// System delegate bridge. Notification taps are converted to the one
/// canonical identifiers-only URL before SwiftUI performs protected routing.
@MainActor
final class HQAppDelegate: NSObject, UIApplicationDelegate, UNUserNotificationCenterDelegate {
    private weak var pushCoordinator: HQPushCoordinator?

    func attach(pushCoordinator: HQPushCoordinator) {
        self.pushCoordinator = pushCoordinator
        UNUserNotificationCenter.current().delegate = self
    }

    func application(
        _ application: UIApplication,
        didRegisterForRemoteNotificationsWithDeviceToken deviceToken: Data
    ) {
        Task { await pushCoordinator?.receiveDeviceToken(deviceToken) }
    }

    func application(
        _ application: UIApplication,
        didFailToRegisterForRemoteNotificationsWithError error: Error
    ) {
        pushCoordinator?.didFailToRegister()
    }

    func userNotificationCenter(
        _ center: UNUserNotificationCenter,
        didReceive response: UNNotificationResponse
    ) async {
        guard let target = HQMessagingLifecycleTargetParser.notificationTarget(
            from: response.notification.request.content.userInfo
        ), let url = HQMessagingLifecycleTargetParser.url(for: target)
        else { return }
        await UIApplication.shared.open(url)
    }
}

