import SwiftUI
import WidgetKit

private struct HQWidgetEntry: TimelineEntry {
    let date: Date
    let snapshot: HQWidgetSnapshot
}

private struct HQWidgetProvider: TimelineProvider {
    func placeholder(in context: Context) -> HQWidgetEntry {
        HQWidgetEntry(
            date: .now,
            snapshot: .unread(
                ownerFingerprint: HQWidgetSnapshot.ownerFingerprint("placeholder"),
                unreadCount: 3,
                isOffline: false
            )
        )
    }

    func getSnapshot(in context: Context, completion: @escaping (HQWidgetEntry) -> Void) {
        completion(entry())
    }

    func getTimeline(in context: Context, completion: @escaping (Timeline<HQWidgetEntry>) -> Void) {
        let current = entry()
        completion(
            Timeline(
                entries: [current],
                policy: .after(current.date.addingTimeInterval(15 * 60))
            )
        )
    }

    private func entry() -> HQWidgetEntry {
        let snapshot = (try? HQWidgetSharedCache()?.load()) ?? .signedOut()
        return HQWidgetEntry(date: .now, snapshot: snapshot)
    }
}

private struct HQWidgetView: View {
    @Environment(\.widgetFamily) private var family
    let entry: HQWidgetEntry

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 7) {
                Image(systemName: "bubble.left.and.bubble.right.fill")
                    .font(.system(size: 13, weight: .semibold))
                    .foregroundStyle(.indigo)
                Text("HQ")
                    .font(.system(size: 14, weight: .bold, design: .rounded))
                Spacer(minLength: 0)
                if entry.snapshot.presentation == .staleOffline {
                    Image(systemName: "wifi.slash")
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .accessibilityLabel("Offline")
                }
            }

            Spacer(minLength: 0)

            switch entry.snapshot.presentation {
            case .signedOut:
                headline("Sign in to HQ")
                detail("Open the app to reconnect.")
            case .empty:
                headline("All caught up")
                detail("No unread messages.")
            case .staleOffline:
                headline(unreadText)
                detail("Last known count · Offline")
            case .unread:
                if family == .systemSmall {
                    Text("\(entry.snapshot.unreadCount)")
                        .font(.system(size: 38, weight: .bold, design: .rounded))
                        .minimumScaleFactor(0.7)
                    detail(entry.snapshot.unreadCount == 1 ? "unread message" : "unread messages")
                } else {
                    headline(unreadText)
                    detail("Open HQ to read and reply.")
                }
            }
        }
        .widgetURL(HQWidgetSharedCache.inboxURL)
        .containerBackground(for: .widget) {
            Color(uiColor: .secondarySystemBackground)
        }
        .accessibilityElement(children: .combine)
    }

    private var unreadText: String {
        "\(entry.snapshot.unreadCount) unread"
    }

    private func headline(_ value: String) -> some View {
        Text(value)
            .font(.system(size: family == .systemSmall ? 19 : 22, weight: .semibold, design: .rounded))
            .lineLimit(2)
            .minimumScaleFactor(0.8)
    }

    private func detail(_ value: String) -> some View {
        Text(value)
            .font(.system(size: 12))
            .foregroundStyle(.secondary)
            .lineLimit(2)
    }
}

@main
struct HQWidget: Widget {
    let kind = "HQUnreadWidget"

    var body: some WidgetConfiguration {
        StaticConfiguration(kind: kind, provider: HQWidgetProvider()) { entry in
            HQWidgetView(entry: entry)
        }
        .configurationDisplayName("HQ Messages")
        .description("See a privacy-safe unread summary and open HQ.")
        .supportedFamilies([.systemSmall, .systemMedium])
    }
}

