+enum HQPushBackgroundRefreshOutcome: Equatable, Sendable {
+    case newData
+    case noData
+    case rejected
+    case failed
+    case timedOut
+
+    var systemResult: UIBackgroundFetchResult {
+        switch self {
+        case .newData: .newData
+        case .noData, .rejected: .noData
+        case .failed, .timedOut: .failed
+        }
+    }
+}
+
+private actor HQBackgroundRefreshGate {
+    private var result: HQPushBackgroundRefreshOutcome?
+    private var continuation: CheckedContinuation<HQPushBackgroundRefreshOutcome, Never>?
+
+    func resolve(_ result: HQPushBackgroundRefreshOutcome) {
+        guard self.result == nil else { return }
+        self.result = result
+        continuation?.resume(returning: result)
+        continuation = nil
+    }
+
+    func wait() async -> HQPushBackgroundRefreshOutcome {
+        if let result { return result }
+        return await withCheckedContinuation { continuation = $0 }
+    }
+}
+
+/// Races a cooperative authoritative refresh against a hard deadline. The
+/// operation runs in an unstructured task so an uncooperative dependency
+/// cannot keep the delegate completion handler alive past the deadline.
+enum HQBackgroundRefreshRunner {
+    static func run(
+        timeoutNanoseconds: UInt64,
+        operation: @escaping @MainActor @Sendable () async throws -> Bool
+    ) async -> HQPushBackgroundRefreshOutcome {
+        let gate = HQBackgroundRefreshGate()
+        let operationTask = Task { @MainActor in
+            do {
+                let changed = try await operation()
+                await gate.resolve(changed ? .newData : .noData)
+            } catch is CancellationError {
+                // The deadline owns the result after cancellation.
+            } catch {
+                await gate.resolve(.failed)
+            }
+        }
+        let timeoutTask = Task {
+            do {
+                try await Task.sleep(nanoseconds: timeoutNanoseconds)
+                guard !Task.isCancelled else { return }
+                await gate.resolve(.timedOut)
+            } catch {
+                // Cancellation means the operation already resolved the race.
+            }
+        }
+
+        let result = await gate.wait()
+        operationTask.cancel()
+        timeoutTask.cancel()
+        return result
+    }
+}
