import Foundation
import XCTest
@testable import HQIOS

final class HQMessagingProtectedStateStoreTests: XCTestCase {
    func testPurgeRemovesEveryMessagingDirectoryButLeavesUnrelatedTemporaryData() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("hq-messaging-purge-\(UUID().uuidString)", isDirectory: true)
        let applicationSupport = root.appendingPathComponent("ApplicationSupport", isDirectory: true)
        let temporary = root.appendingPathComponent("Temporary", isDirectory: true)
        let drafts = applicationSupport
            .appendingPathComponent("HQIOS/MessageDrafts", isDirectory: true)
        let pins = applicationSupport
            .appendingPathComponent("HQIOS/ConversationPins", isDirectory: true)
        let projectFiles = temporary
            .appendingPathComponent("HQProjectFileActions-owned", isDirectory: true)
        let unrelated = temporary.appendingPathComponent("Unrelated", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }

        for directory in [drafts, pins, projectFiles, unrelated] {
            try FileManager.default.createDirectory(
                at: directory,
                withIntermediateDirectories: true
            )
            try Data("protected".utf8).write(
                to: directory.appendingPathComponent("state.bin")
            )
        }

        let store = HQMessagingProtectedStateStore(
            applicationSupportRootURL: applicationSupport,
            temporaryRootURL: temporary
        )
        try await store.purgeProtectedState()

        XCTAssertFalse(FileManager.default.fileExists(atPath: drafts.path))
        XCTAssertFalse(FileManager.default.fileExists(atPath: pins.path))
        XCTAssertFalse(FileManager.default.fileExists(atPath: projectFiles.path))
        XCTAssertTrue(FileManager.default.fileExists(atPath: unrelated.path))
    }
}

import Foundation

/// Owns messaging files independently of any mounted SwiftUI scene so the
/// authentication transaction can fail closed when local cleanup fails.
actor HQMessagingProtectedStateStore: HQProtectedStateStore {
    static let shared = HQMessagingProtectedStateStore()

    private static let projectFileDirectoryPrefix = "HQProjectFileActions-"

    private let draftDirectoryURL: URL
    private let pinDirectoryURL: URL
    private let temporaryRootURL: URL

    init(
        applicationSupportRootURL: URL? = nil,
        temporaryRootURL: URL? = nil
    ) {
        let applicationSupport = applicationSupportRootURL
            ?? FileManager.default.urls(
                for: .applicationSupportDirectory,
                in: .userDomainMask
            )[0]
        draftDirectoryURL = applicationSupport
            .appendingPathComponent("HQIOS/MessageDrafts", isDirectory: true)
        pinDirectoryURL = applicationSupport
            .appendingPathComponent("HQIOS/ConversationPins", isDirectory: true)
        self.temporaryRootURL = temporaryRootURL ?? FileManager.default.temporaryDirectory
    }

    func purgeProtectedState() async throws {
        let fileManager = FileManager.default
        var firstError: Error?

        for directory in [draftDirectoryURL, pinDirectoryURL]
        where fileManager.fileExists(atPath: directory.path) {
            do {
                try fileManager.removeItem(at: directory)
            } catch {
                if firstError == nil { firstError = error }
            }
        }

        do {
            let temporaryItems = try fileManager.contentsOfDirectory(
                at: temporaryRootURL,
                includingPropertiesForKeys: nil,
                options: [.skipsHiddenFiles]
            )
            for item in temporaryItems
            where item.lastPathComponent.hasPrefix(Self.projectFileDirectoryPrefix) {
                do {
                    try fileManager.removeItem(at: item)
                } catch {
                    if firstError == nil { firstError = error }
                }
            }
        } catch {
            if fileManager.fileExists(atPath: temporaryRootURL.path), firstError == nil {
                firstError = error
            }
        }

        if let firstError { throw firstError }
    }
}

