import UserNotifications
import XCTest
@testable import HQIOS

final class HQMessagingSettingsTests: XCTestCase {
    func testPermissionCopyDistinguishesNotRequestedDeniedAndQuietDelivery() {
        XCTAssertEqual(HQMessagingNotificationPermissionPresentation(status: .notDetermined).title, "Not requested")
        XCTAssertEqual(HQMessagingNotificationPermissionPresentation(status: .denied).title, "Off")
        XCTAssertEqual(HQMessagingNotificationPermissionPresentation(status: .authorized).title, "Allowed")
        XCTAssertEqual(HQMessagingNotificationPermissionPresentation(status: .provisional).title, "Quiet delivery")
        XCTAssertEqual(HQMessagingNotificationPermissionPresentation(status: .ephemeral).title, "Temporary permission")
        XCTAssertFalse(HQMessagingNotificationPermissionPresentation(status: .authorized).detail.contains("registered"))
    }
}

import SwiftUI
import UIKit
import UserNotifications

struct HQMessagingNotificationPermissionPresentation: Equatable {
    let title: String
    let detail: String

    init(status: UNAuthorizationStatus) {
        switch status {
        case .notDetermined:
            title = "Not requested"
            detail = "HQ has not received notification permission on this device."
        case .denied:
            title = "Off"
            detail = "Allow notifications in iOS Settings to receive alerts from HQ."
        case .authorized:
            title = "Allowed"
            detail = "iOS permits notifications. Delivery also depends on your connection and HQ device registration."
        case .provisional:
            title = "Quiet delivery"
            detail = "Notifications can appear quietly in Notification Center. Change alert behavior in iOS Settings."
        case .ephemeral:
            title = "Temporary permission"
            detail = "iOS has granted temporary notification permission."
        @unknown default:
            title = "Unknown"
            detail = "Review this app’s notification permission in iOS Settings."
        }
    }
}

struct HQMessagingSettingsView: View {
    let accountName: String
    let accountSubtitle: String
    let onSignOut: @MainActor () -> Void
    @Environment(\.openURL) private var openURL
    @Environment(\.scenePhase) private var scenePhase
    @State private var notificationPermission: HQMessagingNotificationPermissionPresentation?
    @State private var settingsError: String?

    var body: some View {
        Form {
            Section("Account") {
                VStack(alignment: .leading, spacing: 4) {
                    Text(accountName).font(.headline)
                    if !accountSubtitle.isEmpty {
                        Text(accountSubtitle).font(.subheadline).foregroundStyle(.secondary)
                    }
                }
                .padding(.vertical, 4)
                .accessibilityElement(children: .combine)
                .accessibilityIdentifier("messages.settings.account")
            }

            Section {
                LabeledContent("Permission", value: notificationPermission?.title ?? "Checking…")
                    .accessibilityIdentifier("messages.settings.notifications.status")
                Button {
                    guard let url = URL(string: UIApplication.openNotificationSettingsURLString) else { return }
                    settingsError = nil
                    openURL(url) { accepted in
                        if !accepted { settingsError = "Couldn’t open iOS Settings. Open Settings on your iPhone and choose Notifications, then HQ." }
                    }
                } label: {
                    Label("Manage in iOS Settings", systemImage: "arrow.up.forward.app")
                        .frame(minHeight: 44)
                }
                .accessibilityIdentifier("messages.settings.notifications.open")
                if let settingsError {
                    Text(settingsError).font(.footnote).foregroundStyle(.secondary)
                        .accessibilityIdentifier("messages.settings.notifications.error")
                }
            } header: {
                Text("Notifications")
            } footer: {
                Text(notificationPermission?.detail ?? "Checking this device’s notification permission.")
            }

            Section("About") {
                LabeledContent("App", value: "HQ")
                LabeledContent("Version", value: versionLabel)
                    .accessibilityIdentifier("messages.settings.version")
            }

            Section {
                Button("Sign out", systemImage: "rectangle.portrait.and.arrow.right", role: .destructive) {
                    onSignOut()
                }
                .frame(minHeight: 44)
                .accessibilityIdentifier("messages.settings.sign-out")
            } footer: {
                Text("Signing out removes this account’s protected data from this device.")
            }
        }
        .accessibilityIdentifier("messages.settings.ready")
        .task { await refreshPermission() }
        .onChange(of: scenePhase) { _, phase in
            if phase == .active { Task { await refreshPermission() } }
        }
    }

    private var versionLabel: String {
        let version = Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String
        let build = Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String
        switch (version, build) {
        case let (version?, build?): "\(version) (\(build))"
        case let (version?, nil): version
        case let (nil, build?): "Build \(build)"
        case (nil, nil): "Development build"
        }
    }

    @MainActor
    private func refreshPermission() async {
        let settings = await UNUserNotificationCenter.current().notificationSettings()
        guard !Task.isCancelled else { return }
        notificationPermission = .init(status: settings.authorizationStatus)
    }
}

